window.__votdWeek && window.__votdWeek({"week":"2028-11-13","reading":"Ether 6–11","days":[{"d":"2028-11-13","ref":"Ether 6:9","b":"Ether","c":6,"v":9,"he":"וַיְזַמְּרוּ תְהִלּוֹת לַיהוָה אַף אֲחִי יֶרֶד זִמֵּר תְּהִלּוֹת לַיהוָה וַיּוֹדֶה וַיְהַלֵּל אֶת־יְהוָה כׇּל־הַיּוֹם וּבְבוֹא הַלַּיְלָה לֹא חָדְלוּ מֵהַלֵּל אֶת־יְהוָה׃","en":"And they did sing praises unto the Lord; yea, the brother of Jared did sing praises unto the Lord, and he did thank and praise the Lord all the day long; and when the night came, they did not cease to praise the Lord."},{"d":"2028-11-14","ref":"Ether 8:21","b":"Ether","c":8,"v":21,"he":"וְהֵם הֵבִיאוּ אֶת־הַשְׁמָדַת הָעָם־הַזֶּה אֲשֶׁר־אֲנִי מְדַבֵּר עָלָיו עַתָּה וְגַם לְהַשְׁמָדַת עַם נֶפִי׃","en":"And they have caused the destruction of this people of whom I am now speaking, and also the destruction of the people of Nephi."},{"d":"2028-11-15","ref":"Ether 9:17","b":"Ether","c":9,"v":17,"he":"וַיְהִי לָהֶם כׇּל־מִינֵי פְרִי וְדָגָן וּמֶשִׁי וּבוּץ וְזָהָב וָכֶסֶף וַחֲפָצִים יְקָרִים׃","en":"Having all manner of fruit, and of grain, and of silks, and of fine linen, and of gold, and of silver, and of precious things;"},{"d":"2028-11-16","ref":"Ether 9:18","b":"Ether","c":9,"v":18,"he":"וְגַם כׇּל־מִינֵי בְהֵמוֹת בָּקָר וּפָרוֹת וְצֹאן וַחֲזִירִים וְעִזִּים וְגַם מִינֵי חַיּוֹת רַבּוֹת אֲחֵרוֹת אֲשֶׁר הוֹעִילוּ לְמַאֲכַל הָאָדָם׃","en":"And also all manner of cattle, of oxen, and cows, and of sheep, and of swine, and of goats, and also many other kinds of animals which were useful for the food of man."},{"d":"2028-11-17","ref":"Ether 10:22","b":"Ether","c":10,"v":22,"he":"וַיִּהְיוּ חֲרוּצִים מְאֹד וַיִּקְנוּ וַיִּמְכְּרוּ וַיִּסְחֲרוּ אִישׁ עִם־רֵעֵהוּ לְמַעַן הַשִּׂיג בֶּצַע׃","en":"And they were exceedingly industrious, and they did buy and sell and traffic one with another, that they might get gain."},{"d":"2028-11-18","ref":"Ether 10:24","b":"Ether","c":10,"v":24,"he":"וַיְהִי לָהֶם מֶשִׁי וּבוּץ מׇשְׁזָר וַיַּעֲשׂוּ כׇּל־מִינֵי בֶגֶד לְכַסּוֹת אֶת־עֵירֹמָם׃","en":"And they did have silks, and fine-twined linen; and they did work all manner of cloth, that they might clothe themselves from their nakedness."},{"d":"2028-11-19","ref":"Ether 11:21","b":"Ether","c":11,"v":21,"he":"וְכִי יִשְׁלַח אוֹ יָבִיא יְהוָה אֱלֹהִים עַם אַחֵר לָרֶשֶׁת אֶת־הָאָרֶץ בִּגְבוּרָתוֹ כַּאֲשֶׁר הֵבִיא אֶת־אֲבוֹתֵיהֶם׃","en":"And that the Lord God would send or bring forth another people to possess the land, by his power, after the manner by which he brought their fathers."}]});
